      "title": "Finding jobs abroad",
      "claims": [
        {
          "text": "LinkedIn is recommended for job hunting",
          "evidence": [18]
        },
        {
          "text": "Applying to many positions (about 100) yielded only 3 interviews",
          "evidence": [21]
        },
        {
          "text": "Applying to any vacancy without language requirement increased interview chances",
          "evidence": [36]
        },
        {
          "text": "Higher salary offers exist but many accept minimal pay to secure a job",
          "evidence": [37]
        }
      ]
    },
    {
