      "claims": [
        {
          "text": "Salaries in Europe are generally higher than in Ukraine, but few pay attention to it",
          "evidence": [35]
        },
        {
          "text": "The respondent’s salary was higher than expected but accepted the minimum offered",
          "evidence": [37]
        }
      ]
    }
  ],
